contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address asset) public payable {
        bool supported = c.lrtConfig().isSupportedAsset(asset);

        uint256 balBefore = 0;
        if (supported) {
            balBefore = IERC20(asset).balanceOf(address(c));
        }

        bool reverted;
        uint256 lyingInPool;
        uint256 lyingInNDCs;
        uint256 stakedInEigenLayer;
        try c.getAssetDistributionData(asset) returns (uint256 a, uint256 b, uint256 d) {
            lyingInPool = a;
            lyingInNDCs = b;
            stakedInEigenLayer = d;
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == !supported);
        assert(!supported || lyingInPool == balBefore);
    }

    receive() external payable {}
}

