contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address asset, uint256 amount) public payable {
        require(true);
        address lrtConfigAddr = address(c.lrtConfig());
        require(lrtConfigAddr != address(0));
        ILRTConfig lrtConfig = ILRTConfig(lrtConfigAddr);
        require(lrtConfig.isSupportedAsset(asset));
        address lrtOracleAddress = lrtConfig.getContract(LRTConstants.LRT_ORACLE);
        require(lrtOracleAddress != address(0));
        ILRTOracle lrtOracle = ILRTOracle(lrtOracleAddress);
        uint256 assetPrice = lrtOracle.getAssetPrice(asset);
        uint256 rsethPrice = lrtOracle.getRSETHPrice();
        require(rsethPrice != 0);
        uint256 expected = (amount * assetPrice) / rsethPrice;
        uint256 returned = c.getRsETHAmountToMint(asset, amount);
        assert(returned == expected);
    }
    receive() external payable {}
}

